c1_hex=""
c2_hex=""

#convert the hexadecimal strings in to  raw byte so python can run bitwise maths on them
c1= bytes.fromhex(c1_hex)
c2= bytes.fromhex(c2_hex)
p1= open("expense-form.txt", "rb").read()

p2= bytes(a ^ b ^ c for a, b, c in zip(c1[48:], c2[48:-8], p1))

print( p2.decode("utf-8", errors="replace"))



